/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { MAT_DIALOG_DATA } from '@angular/material/dialog';
import { Subject } from 'rxjs';
import { LongTaskViewComponent } from './long-task-view.component';
import { LongTask } from '@shared/data/long-task.model';

describe('LongTaskViewComponent', () => {
  it('updates progress from stream', () => {
    const progress$ = new Subject<LongTask>();
    const data = { title: 'Task title', progress: progress$ };

    TestBed.configureTestingModule({
      imports: [LongTaskViewComponent],
      providers: [{ provide: MAT_DIALOG_DATA, useValue: data }],
    });

    const fixture = TestBed.createComponent(LongTaskViewComponent);
    const component = fixture.componentInstance;

    progress$.next({
      uid: '1',
      detailStatus: 'PROCESSING',
      steps: [
        {
          name: 'Step 1',
          stepStatus: 'PROCESSING',
          totalItems: 10,
          processedItems: 5,
          oks: [],
          warns: [],
          errors: [],
        },
        {
          name: 'Step 2',
          stepStatus: 'FINISHED',
          totalItems: 0,
          processedItems: 0,
          oks: ['ok'],
          warns: [],
          errors: [],
        },
      ],
    });

    fixture.detectChanges();

    expect(component.title).toBe('Task title');
    expect(component.status).toBe('PROCESSING');
    expect(component.tasks.length).toBe(2);
    expect(component.known).toBeTrue();
    expect(component.step).toBe('Step 1');
    expect(component.currentStepProgress).toBeGreaterThan(0);
    expect(component.globalStepsProgress).toBe(50);
  });

  it('detects homogeneous results', () => {
    const data = { progress: new Subject<LongTask>() };
    TestBed.configureTestingModule({
      imports: [LongTaskViewComponent],
      providers: [{ provide: MAT_DIALOG_DATA, useValue: data }],
    });

    const fixture = TestBed.createComponent(LongTaskViewComponent);
    const component = fixture.componentInstance;

    expect(
      component.allTheSame({
        name: 'Step',
        stepStatus: 'FINISHED',
        totalItems: 0,
        processedItems: 0,
        oks: ['ok'],
        warns: [],
        errors: [],
      }),
    ).toBeTrue();
  });
});
